import { useEffect, useState } from "react";
import { ArrowLeft, Crown } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { fetchLeaderboard } from "@/lib/leaderboard";
import type { LeaderboardEntry } from "@/types/platform";

export default function Leaderboard() {
  const navigate = useNavigate();
  const [entries, setEntries] = useState<LeaderboardEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    fetchLeaderboard().then((data) => {
      if (!cancelled) {
        setEntries(data);
        setLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <main className="min-h-screen bg-[radial-gradient(circle_at_top,_rgba(34,211,238,0.12),_transparent_26%),linear-gradient(180deg,_#020617_0%,_#0f172a_100%)] px-4 py-6 text-slate-50">
      <div className="mx-auto max-w-5xl space-y-5">
        <button
          type="button"
          onClick={() => navigate("/lobby")}
          className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-sm text-slate-100 transition hover:bg-white/10"
        >
          <ArrowLeft className="size-4" />
          返回大厅
        </button>

        <section className="rounded-[2rem] border border-white/10 bg-slate-950/75 p-5 shadow-[0_30px_80px_rgba(15,23,42,0.4)] backdrop-blur-xl">
          <div className="flex items-center gap-3">
            <Crown className="size-6 text-amber-200" />
            <div>
              <p className="text-xs uppercase tracking-[0.35em] text-amber-100/70">Leaderboard</p>
              <h1 className="mt-2 font-display text-4xl text-slate-50">天梯榜</h1>
            </div>
          </div>

          <div className="mt-5 overflow-hidden rounded-[1.5rem] border border-white/10">
            <div className="grid grid-cols-[72px_1.1fr_120px_120px_120px] bg-white/5 px-4 py-3 text-xs uppercase tracking-[0.25em] text-slate-400">
              <span>排名</span>
              <span>玩家</span>
              <span>段位</span>
              <span>积分</span>
              <span>战绩</span>
            </div>

            {loading && (
              <div className="px-4 py-6 text-sm text-slate-400">正在读取排行榜数据...</div>
            )}

            {!loading && entries.length === 0 && (
              <div className="px-4 py-6 text-sm text-slate-400">
                还没有读到排行榜数据。请先在 Supabase 中执行数据表脚本，并完成至少 1 个正式账号注册。
              </div>
            )}

            {!loading && entries.map((entry, index) => (
              <div
                key={entry.userId}
                className="grid grid-cols-[72px_1.1fr_120px_120px_120px] border-t border-white/10 px-4 py-4 text-sm text-slate-200"
              >
                <span className="font-semibold text-amber-100">#{index + 1}</span>
                <div>
                  <p className="font-medium text-slate-50">{entry.displayName}</p>
                  <p className="text-xs text-slate-400">@{entry.username}</p>
                </div>
                <span>{entry.rankTier}</span>
                <span>{entry.ratingPoints}</span>
                <span>
                  {entry.wins}胜 {entry.losses}负
                </span>
              </div>
            ))}
          </div>
        </section>
      </div>
    </main>
  );
}
