import { create } from "zustand";
import { persist } from "zustand/middleware";
import { fetchProfile } from "@/lib/account";
import { getRankByPoints } from "@/lib/ranks";
import { supabase } from "@/lib/supabase";
import type { PlayerAccessMode, UserProfile } from "@/types/platform";

interface SessionStore {
  ready: boolean;
  mode: PlayerAccessMode | null;
  profile: UserProfile | null;
  authUserId: string | null;
  errorMessage: string | null;
  setReady: (ready: boolean) => void;
  setErrorMessage: (message: string | null) => void;
  startGuestMode: () => void;
  hydrateFromSupabase: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  clearSession: () => void;
}

function createGuestProfile(): UserProfile {
  return {
    id: "guest",
    username: "guest",
    displayName: "游客占星师",
    ratingPoints: 0,
    rankTier: getRankByPoints(0).name,
    wins: 0,
    losses: 0,
    isGuest: true,
  };
}

export const useSessionStore = create<SessionStore>()(
  persist(
    (set, get) => ({
      ready: false,
      mode: null,
      profile: null,
      authUserId: null,
      errorMessage: null,
      setReady: (ready) => set({ ready }),
      setErrorMessage: (message) => set({ errorMessage: message }),
      startGuestMode: () =>
        set({
          ready: true,
          mode: "guest",
          profile: createGuestProfile(),
          authUserId: null,
          errorMessage: null,
        }),
      hydrateFromSupabase: async () => {
        const { data, error } = await supabase.auth.getUser();
        if (error || !data.user) {
          set({ ready: true });
          return;
        }

        const profile = await fetchProfile(data.user.id);
        set({
          ready: true,
          mode: "authenticated",
          authUserId: data.user.id,
          profile: profile ?? null,
          errorMessage: null,
        });
      },
      refreshProfile: async () => {
        const authUserId = get().authUserId;
        if (!authUserId) {
          return;
        }

        const profile = await fetchProfile(authUserId);
        set({
          profile,
        });
      },
      clearSession: () =>
        set({
          ready: true,
          mode: null,
          profile: null,
          authUserId: null,
          errorMessage: null,
        }),
    }),
    {
      name: "arcane-session-store",
      partialize: (state) => ({
        mode: state.mode,
        profile: state.profile,
        authUserId: state.authUserId,
      }),
    },
  ),
);
