import { LogOut, Shield, Smartphone, Swords, Trophy, UserPlus, Users } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { signOutAccount } from "@/lib/account";
import { RANKED_RESULT_POINTS } from "@/lib/ranks";
import { useGameStore } from "@/store/gameStore";
import { useSessionStore } from "@/store/sessionStore";

export default function Lobby() {
  const navigate = useNavigate();
  const profile = useSessionStore((state) => state.profile);
  const mode = useSessionStore((state) => state.mode);
  const clearSession = useSessionStore((state) => state.clearSession);
  const setGameMode = useGameStore((state) => state.setGameMode);

  const isGuest = mode === "guest" || profile?.isGuest;

  const handleGuestPve = () => {
    setGameMode("pve");
    navigate("/battle");
  };

  const handleLocalPvp = () => {
    setGameMode("pvp");
    navigate("/battle");
  };

  const handleSignOut = async () => {
    if (!isGuest) {
      await signOutAccount();
    }
    clearSession();
    navigate("/auth");
  };

  return (
    <main className="min-h-screen bg-[radial-gradient(circle_at_top,_rgba(34,211,238,0.14),_transparent_24%),radial-gradient(circle_at_bottom_right,_rgba(245,158,11,0.16),_transparent_28%),linear-gradient(180deg,_#020617_0%,_#0f172a_100%)] px-4 py-4 text-slate-50 md:py-6">
      <div className="mx-auto flex max-w-7xl flex-col gap-5">
        <section className="rounded-[2rem] border border-white/10 bg-slate-950/70 p-5 shadow-[0_30px_80px_rgba(15,23,42,0.35)] backdrop-blur-xl">
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <div>
              <p className="text-xs uppercase tracking-[0.35em] text-cyan-200/70">Arcane Lobby</p>
              <h1 className="mt-3 font-display text-4xl md:text-5xl">{profile?.displayName ?? "占星师"}</h1>
              <p className="mt-2 text-sm text-slate-300">
                当前身份：{isGuest ? "游客试玩" : "正式账号"} | 当前段位：{profile?.rankTier ?? "知灵"} | 总积分：
                {profile?.ratingPoints ?? 0}
              </p>
            </div>
            <button
              type="button"
              onClick={handleSignOut}
              className="inline-flex items-center gap-2 self-start rounded-full border border-white/10 bg-white/5 px-4 py-2 text-sm text-slate-100 transition hover:bg-white/10"
            >
              <LogOut className="size-4" />
              {isGuest ? "退出游客模式" : "退出登录"}
            </button>
          </div>
        </section>

        <section className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]">
          <div className="grid gap-5 md:grid-cols-2">
            <button
              type="button"
              disabled={isGuest}
              onClick={() => navigate("/ranked")}
              className="rounded-[2rem] border border-amber-300/20 bg-amber-300/10 p-5 text-left transition hover:bg-amber-300/15 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <Trophy className="size-6 text-amber-200" />
              <p className="mt-4 text-2xl font-semibold text-slate-50">随机匹配</p>
              <p className="mt-2 text-sm leading-6 text-slate-300">
                进入天梯匹配，赢家 +{RANKED_RESULT_POINTS.win} 分，失败 -1 分，最低不会低于 0 分。
              </p>
            </button>

            <button
              type="button"
              disabled={isGuest}
              onClick={() => navigate("/rooms")}
              className="rounded-[2rem] border border-cyan-300/20 bg-cyan-300/10 p-5 text-left transition hover:bg-cyan-300/15 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <Users className="size-6 text-cyan-200" />
              <p className="mt-4 text-2xl font-semibold text-slate-50">自定义房间</p>
              <p className="mt-2 text-sm leading-6 text-slate-300">
                支持房间码邀请和好友直邀，1v1 自定义房间不计积分，也不计段位。
              </p>
            </button>

            <button
              type="button"
              disabled={isGuest}
              onClick={() => navigate("/friends")}
              className="rounded-[2rem] border border-white/10 bg-white/5 p-5 text-left transition hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <UserPlus className="size-6 text-emerald-200" />
              <p className="mt-4 text-2xl font-semibold text-slate-50">好友系统</p>
              <p className="mt-2 text-sm leading-6 text-slate-300">
                管理好友、好友申请和邀请记录，后续从好友列表直接发起约战。
              </p>
            </button>

            <button
              type="button"
              disabled={isGuest}
              onClick={() => navigate("/leaderboard")}
              className="rounded-[2rem] border border-white/10 bg-white/5 p-5 text-left transition hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-50"
            >
              <Shield className="size-6 text-violet-200" />
              <p className="mt-4 text-2xl font-semibold text-slate-50">天梯榜</p>
              <p className="mt-2 text-sm leading-6 text-slate-300">
                按总积分排名，积分相同则优先胜场更多的玩家。
              </p>
            </button>
          </div>

          <div className="space-y-5">
            <div className="rounded-[2rem] border border-white/10 bg-slate-950/75 p-5 shadow-[0_30px_80px_rgba(15,23,42,0.4)] backdrop-blur-xl">
              <div className="flex items-center gap-3">
                <Swords className="size-5 text-amber-200" />
                <p className="text-lg font-semibold text-slate-50">当前可玩的模式</p>
              </div>

              <div className="mt-4 grid gap-3">
                <button
                  type="button"
                  onClick={handleGuestPve}
                  className="rounded-[1.5rem] border border-cyan-300/20 bg-cyan-300/10 px-4 py-4 text-left transition hover:bg-cyan-300/15"
                >
                  <p className="font-medium text-slate-50">人机练习</p>
                  <p className="mt-2 text-sm text-slate-300">无论是否登录，都可以直接进入当前的人机对战原型。</p>
                </button>

                <button
                  type="button"
                  disabled={isGuest}
                  onClick={handleLocalPvp}
                  className="rounded-[1.5rem] border border-white/10 bg-white/5 px-4 py-4 text-left transition hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  <p className="font-medium text-slate-50">本地双人</p>
                  <p className="mt-2 text-sm text-slate-300">继续保留当前本机双人玩法，方便规则测试和线下切磋。</p>
                </button>
              </div>
            </div>

            <div className="rounded-[2rem] border border-white/10 bg-slate-950/75 p-5 shadow-[0_30px_80px_rgba(15,23,42,0.4)] backdrop-blur-xl">
              <div className="flex items-center gap-3">
                <Smartphone className="size-5 text-cyan-200" />
                <p className="text-lg font-semibold text-slate-50">双端体验</p>
              </div>
              <p className="mt-3 text-sm leading-6 text-slate-300">
                手机端将以横屏大厅和横屏战斗界面为主，PC 与手机共用一套账户、好友和积分数据。
              </p>
              {isGuest && (
                <div className="mt-4 rounded-[1.5rem] border border-amber-300/20 bg-amber-300/10 px-4 py-3 text-sm text-amber-50">
                  当前处于游客模式：随机匹配、天梯榜、好友、自定义房间都已锁定，仅保留人机练习。
                </div>
              )}
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}
