import { useMemo, useState } from "react";
import { KeyRound, ShieldCheck, UserRound } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { ensureProfile, signInWithUsername, signUpWithUsername } from "@/lib/account";
import { useSessionStore } from "@/store/sessionStore";
import type { AuthView } from "@/types/platform";

export default function Auth() {
  const navigate = useNavigate();
  const [view, setView] = useState<AuthView>("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const hydrateFromSupabase = useSessionStore((state) => state.hydrateFromSupabase);
  const startGuestMode = useSessionStore((state) => state.startGuestMode);
  const modeLabel = useMemo(() => (view === "login" ? "登录" : "注册"), [view]);

  const handleSubmit = async () => {
    const trimmedUsername = username.trim();
    if (!trimmedUsername || password.length < 6) {
      setMessage("用户名不能为空，密码至少需要 6 位。");
      return;
    }

    try {
      setSubmitting(true);
      setMessage(null);

      if (view === "register") {
        const data = await signUpWithUsername(trimmedUsername, password);
        if (data.user) {
          await ensureProfile(data.user.id, trimmedUsername);
        }
      } else {
        await signInWithUsername(trimmedUsername, password);
      }

      await hydrateFromSupabase();
      navigate("/lobby");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : `${modeLabel}失败，请稍后重试。`);
    } finally {
      setSubmitting(false);
    }
  };

  const handleGuestStart = () => {
    startGuestMode();
    navigate("/lobby");
  };

  return (
    <main className="min-h-screen bg-[radial-gradient(circle_at_top,_rgba(34,211,238,0.14),_transparent_24%),radial-gradient(circle_at_bottom_right,_rgba(245,158,11,0.16),_transparent_28%),linear-gradient(180deg,_#020617_0%,_#0f172a_100%)] px-4 py-6 text-slate-50">
      <div className="mx-auto flex min-h-[calc(100vh-3rem)] max-w-6xl items-center justify-center">
        <div className="grid w-full gap-5 lg:grid-cols-[1.1fr_420px]">
          <section className="rounded-[2rem] border border-white/10 bg-slate-950/60 p-6 shadow-[0_30px_80px_rgba(15,23,42,0.35)] backdrop-blur-xl md:p-8">
            <p className="text-xs uppercase tracking-[0.35em] text-cyan-200/70">Arcane Online</p>
            <h1 className="mt-4 font-display text-5xl text-slate-50 md:text-6xl">账号、好友与天梯</h1>
            <p className="mt-4 max-w-2xl text-base leading-7 text-slate-300">
              现在开始接入在线平台能力。正式用户可以使用好友、随机匹配、天梯榜、自定义开房和段位系统；游客只开放人机体验。
            </p>

            <div className="mt-8 grid gap-4 md:grid-cols-3">
              <div className="rounded-[1.5rem] border border-white/10 bg-white/5 p-4">
                <ShieldCheck className="size-5 text-emerald-200" />
                <p className="mt-3 font-medium text-slate-100">账号安全</p>
                <p className="mt-2 text-sm text-slate-400">接入 Supabase 认证与数据存储，后续按真实账号管理你的战绩和社交数据。</p>
              </div>
              <div className="rounded-[1.5rem] border border-white/10 bg-white/5 p-4">
                <UserRound className="size-5 text-cyan-200" />
                <p className="mt-3 font-medium text-slate-100">好友社交</p>
                <p className="mt-2 text-sm text-slate-400">支持好友列表、房间码邀请和好友直邀，后续可以在大厅快速拉人 1v1。</p>
              </div>
              <div className="rounded-[1.5rem] border border-white/10 bg-white/5 p-4">
                <KeyRound className="size-5 text-amber-200" />
                <p className="mt-3 font-medium text-slate-100">游客体验</p>
                <p className="mt-2 text-sm text-slate-400">无需登录即可试玩，但游客只能进行人机对战，其他在线功能默认锁定。</p>
              </div>
            </div>
          </section>

          <section className="rounded-[2rem] border border-white/10 bg-slate-950/75 p-6 shadow-[0_30px_80px_rgba(15,23,42,0.4)] backdrop-blur-xl">
            <div className="flex gap-2 rounded-full border border-white/10 bg-white/5 p-1">
              <button
                type="button"
                onClick={() => setView("login")}
                className={`flex-1 rounded-full px-4 py-2 text-sm transition ${view === "login" ? "bg-cyan-300/15 text-cyan-50" : "text-slate-300"}`}
              >
                登录
              </button>
              <button
                type="button"
                onClick={() => setView("register")}
                className={`flex-1 rounded-full px-4 py-2 text-sm transition ${view === "register" ? "bg-amber-300/15 text-amber-50" : "text-slate-300"}`}
              >
                注册
              </button>
            </div>

            <div className="mt-6 space-y-4">
              <div>
                <label className="mb-2 block text-sm text-slate-300">用户名</label>
                <input
                  value={username}
                  onChange={(event) => setUsername(event.target.value)}
                  placeholder="输入你的对战昵称"
                  className="w-full rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-slate-50 outline-none transition focus:border-cyan-300/50"
                />
              </div>
              <div>
                <label className="mb-2 block text-sm text-slate-300">密码</label>
                <input
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                  type="password"
                  placeholder="至少 6 位"
                  className="w-full rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-slate-50 outline-none transition focus:border-cyan-300/50"
                />
              </div>

              {message && (
                <div className="rounded-2xl border border-amber-300/20 bg-amber-300/10 px-4 py-3 text-sm text-amber-50">
                  {message}
                </div>
              )}

              <button
                type="button"
                disabled={submitting}
                onClick={handleSubmit}
                className="w-full rounded-full border border-cyan-300/30 bg-cyan-300/10 px-5 py-3 text-sm text-cyan-50 transition hover:bg-cyan-300/20 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {submitting ? "提交中..." : modeLabel}
              </button>

              <button
                type="button"
                onClick={handleGuestStart}
                className="w-full rounded-full border border-white/10 bg-white/5 px-5 py-3 text-sm text-slate-200 transition hover:bg-white/10"
              >
                游客登录，只试玩人机模式
              </button>

              <p className="text-xs leading-6 text-slate-500">
                当前为“用户名 + 密码外观”方案。底层会自动映射到 Supabase 认证，不需要玩家直接使用邮箱。
              </p>
            </div>
          </section>
        </div>
      </div>
    </main>
  );
}
